EDITORIAL_BAN = ["network breathes", "not a conversation", "wrong by construction", "tight cycle",
                 "workhorse", "dissolving", "boundaries are tested", "teaches padding", "paying off",
                 "buys nothing", "honest use", "informal lanes", "honesty rule", "dying quietly",
                 "which is the point", "the one idea", "here is the trap", "keeps it honest"]


def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    import re as _re
    blob = json.dumps({"l": lessons, "q": questions}, ensure_ascii=False)
    if "ERPNext" in blob:
        problems.append(f"  {name}: ERPNext branding leakage")
    if _re.search(r"\b[Ll]aws?\b", blob):
        problems.append(f"  {name}: 'law' register leakage")
    low = blob.lower()
    for marker in ["certified professional", "the consultant", "consultants", "the academy",
                   "this academy", "engagement", "constitution", "costume", "scar tissue",
                   "witness", "testimony"] + EDITORIAL_BAN:
        if marker in low:
            problems.append(f"  {name}: banned phrase '{marker}'")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.184.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.183.0"' not in init:
        sys.exit("ABORT: not at v3.183.0.")
    if "stock_health" not in data:
        sys.exit("ABORT: stock_health module not found in data file.")

    problems = _validate("INV7", LESSONS_I7, QUESTIONS_I7, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    bank = rebalance(list(QUESTIONS_I7))
    dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
    if max(dist.values()) > 10:
        print(f"ABORT — INV7 spread failed: {dist}")
        sys.exit(1)
    total = sum(len(l["html"]) for l in LESSONS_I7)
    print(f"INV 7 v3: {len(LESSONS_I7)} chapters ({total:,} chars, min {min(len(l['html']) for l in LESSONS_I7):,}), bank {len(bank)}, spread {dist}")

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    data["stock_health"]["lessons"] = LESSONS_I7
    data["stock_health"]["questions"] = bank
    data["stock_health"]["desc"] = ("Stock health and analytics in ZhiftERP: the stock aging read with its bands, the over-ninety-day percentage, and the carried working list; movement classification and the two-dimensional grid with seasonal and probation exclusions; sell-through analytics — the network view, the divergence read, the group rollup, and the like-window rule; the five dead-stock lanes in preference order with the monthly review's decision list; upstream prevention — reorder hygiene, purchasing feedback, the range review and delisting execution, and the new-item probation read; and stock turns, the joined margin reading, and the five-section monthly health page.")

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.183.0"', '"3.184.0"'))
    print("  data: INVENTORY 7 lessons + bank REPLACED (style v3, formal manual register)")
    print("wrote __version__ -> 3.184.0")


if __name__ == "__main__":
    main()
